def longest_common_prefix(strs):
    if not strs:
        return ''

    root = {}
    END = '$'
    for s in strs:
        node = root
        for ch in s:
            node = node.setdefault(ch, {})
        node[END] = True

    prefix = []
    node = root
    while True:
        keys = [k for k in node if k != END]
        if len(keys) != 1 or END in node:
            break
        ch = keys[0]
        prefix.append(ch)
        node = node[ch]

    return ''.join(prefix)

